// Bad example: Using dynamic SQL query construction vulnerable to SQL injection
public boolean authenticate(HttpServletRequest request) throws SQLException {
    String username = request.getParameter("username");
    String password = request.getParameter("password");

    Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test");
    Statement stmt = conn.createStatement();

    // Vulnerable: concatenating user input directly into SQL query
    String query = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
    ResultSet rs = stmt.executeQuery(query);

    return rs.next();  // Returns true if credentials match
}
```

***
```java
// Good example: Using parameterized queries to prevent SQL injection
public boolean authenticateSecure(HttpServletRequest request) throws SQLException {
    String username = request.getParameter("username");
    String password = request.getParameter("password");

    Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test");

    // Secure: parameterized query prevents SQL injection
    String query = "SELECT * FROM users WHERE username=? AND password=?";
    PreparedStatement stmt = conn.prepareStatement(query);
    stmt.setString(1, username);  // Safely bind parameters
    stmt.setString(2, password);

    ResultSet rs = stmt.executeQuery();
    return rs.next();
}
```

